// Jours ouvrables (lu-ve) hors jours fériés genevois et fermetures (AC_JOURS_FERMES = "2027-07-19,2027-07-20").
function paques(a) {
  const b = Math.floor(a / 100), c = a % 100, d = Math.floor(b / 4), e = b % 4, f = Math.floor((b + 8) / 25),
    g = Math.floor((b - f + 1) / 3), h = (19 * (a % 19) + b - d - g + 15) % 30, i = Math.floor(c / 4), k = c % 4,
    l = (32 + 2 * e + 2 * i - h - k) % 7, m = Math.floor(((a % 19) + 11 * h + 22 * l) / 451);
  return DateTime.fromObject({ year: a, month: Math.floor((h + l - 7 * m + 114) / 31), day: ((h + l - 7 * m + 114) % 31) + 1 }, { zone: 'Europe/Zurich' });
}
function feries(a) {
  const p = paques(a), j = (n) => p.plus({ days: n }).toISODate();
  const jeune = DateTime.fromObject({ year: a, month: 9, day: 1 }, { zone: 'Europe/Zurich' });
  const premierDimanche = jeune.plus({ days: (7 - jeune.weekday) % 7 });
  return [a + '-01-01', j(-2), j(1), j(39), j(50), a + '-08-01', premierDimanche.plus({ days: 4 }).toISODate(), a + '-12-25', a + '-12-31']
    .concat(String($env.AC_JOURS_FERMES || '').split(',').map((s) => s.trim()).filter(Boolean));
}
const estOuvrable = (dt) => dt.weekday <= 5 && !feries(dt.year).includes(dt.toISODate());
const maintenant = () => DateTime.now().setZone('Europe/Zurich');

const t = maintenant();
return [{ json: { depuis: t.minus({ days: 7 }).toISODate(), jusque: t.toISODate() } }];

// Jetons signés partagés avec site/api (lib/Jeton.php) : base64url(JSON).base64url(HMAC-SHA256).
// Prérequis : NODE_FUNCTION_ALLOW_BUILTIN=crypto dans l'environnement de n8n.
const crypto = require('crypto');
const b64 = (buf) => Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
function creerJeton(donnees, validiteS) {
  const secret = $env.AC_ACTION_SECRET;
  if (!secret || secret.length < 32) throw new Error('AC_ACTION_SECRET absent ou trop court');
  const d = { ...donnees, x: Math.floor(Date.now() / 1000) + validiteS, n: crypto.randomBytes(4).toString('hex') };
  const charge = b64(JSON.stringify(d));
  return charge + '.' + b64(crypto.createHmac('sha256', secret).update(charge).digest());
}
function verifierJeton(jeton) {
  const secret = $env.AC_ACTION_SECRET || '';
  const [charge, sig] = String(jeton || '').split('.');
  if (!charge || !sig || secret.length < 32) return null;
  const attendue = b64(crypto.createHmac('sha256', secret).update(charge).digest());
  if (attendue.length !== sig.length || !crypto.timingSafeEqual(Buffer.from(attendue), Buffer.from(sig))) return null;
  let d;
  try { d = JSON.parse(Buffer.from(charge.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8')); } catch (e) { return null; }
  if (!d || !d.x || d.x < Date.now() / 1000) return null;
  return d;
}
const lienAction = (donnees, jours) => ($env.AC_N8N_URL || '') + '/webhook/ac-action?t=' + creerJeton(donnees, jours * 86400);
const lienStop = (email) => ($env.AC_N8N_URL || '') + '/webhook/ac-stop?t=' + creerJeton({ a: 'stop', e: email }, 400 * 86400);

const r = $input.first().json || {};
const projets = r.projects || r.items || r.results || r.data || [];
const MOTS = /pl[aâ]trerie|gypserie|faux[- ]plafond|peinture int|acousti|cloison|CFC\s*2(71|77|83|85)|BKP\s*2(71|77|83|85)/i;
const ROMANDS = ['GE', 'VD', 'NE', 'FR', 'VS', 'JU', 'BE'];
const lignes = [];
for (const p of projets) {
  const titre = String(p.title && (p.title.fr || p.title.de || p.title) || p.projectTitle || p.name || '');
  const texte = JSON.stringify(p);
  const canton = String(p.canton || (p.procOffice && p.procOffice.canton) || '');
  if (!MOTS.test(texte) || (canton && !ROMANDS.includes(canton))) continue;
  const delai = p.offerDeadline || p.deadline || (p.dates && p.dates.offerDeadline) || '';
  const jours = delai ? Math.floor((Date.parse(delai) - Date.now()) / 86400000) : null;
  if (jours !== null && jours < 10) continue;
  const etoiles = (/CFC\s*2(71|83|85)|BKP\s*2(71|83|85)/i.test(texte) ? 1 : 0) + (['GE', 'VD'].includes(canton) ? 1 : 0) + (/acousti/i.test(texte) ? 1 : 0);
  const id = p.id || p.projectId || p.projectNumber || '';
  lignes.push({ etoiles, texte: '- ' + '★'.repeat(Math.max(1, etoiles)) + ' ' + titre + ' · ' + (p.procOfficeName || (p.procOffice && p.procOffice.name) || '') + ' · ' + canton
    + ' · délai ' + (delai ? String(delai).slice(0, 10) : '?') + '\n  simap : https://www.simap.ch/project-detail/' + id
    + '\n  Étudier : ' + lienAction({ a: 'simap-etudier', s: String(id), t: titre.slice(0, 120) }, 21) + '\n  Ignorer : ' + lienAction({ a: 'simap-ignorer', s: String(id) }, 21) });
}
lignes.sort((a, b) => b.etoiles - a.etoiles);
const semaine = Math.ceil((Date.now() - Date.UTC(new Date().getUTCFullYear(), 0, 1)) / 604800000);
const texte = (lignes.length ? lignes.map((l) => l.texte).join('\n\n') : "Aucun avis correspondant cette semaine (l'abonnement e-mail de simap reste actif).")
  + (r.error ? '\n\nAttention : la recherche simap a échoué (' + String(r.error.message || r.error).slice(0, 120) + '). Vérifier les paramètres de l\'API.' : '');
return [{ json: { courriel: { de: $env.AC_EMAIL_EXPEDITEUR, a: $env.AC_EMAILS_ASSOCIES, repondre_a: $env.AC_EMAIL_EXPEDITEUR,
  sujet: 'Veille marchés publics · semaine ' + semaine + ' : ' + lignes.length + ' avis à regarder', texte: texte + '\n',
  html: '<pre style="font:16px/1.5 Arial,sans-serif;white-space:pre-wrap">' + texte.replace(/</g, '&lt;').replace(/(https?:\/\/\S+)/g, '<a href="$1">$1</a>') + '</pre>' } } }];

