const texte = projets.map((p) => '- ' + String(p.title && (p.title.fr || p.title) || p.name || '') + ' · adjudicateur : ' + (p.procOfficeName || '') + ' · retenu : ' + (p.awardee || p.winner || '?')).join('\n') || 'Aucune adjudication correspondante.';
return [{ json: { courriel: { de: $env.AC_EMAIL_EXPEDITEUR, a: [$env.AC_EMAILS_ASSOCIES, $env.AC_AGENCE_EMAIL].filter(Boolean).join(','), repondre_a: $env.AC_EMAIL_EXPEDITEUR,
  sujet: 'Adjudications du mois (CFC 271/283/285, Suisse romande)', texte: texte + '\n', html: '<pre>' + texte.replace(/</g, '&lt;') + '</pre>' } } }];
